{
  "contract": "SummoningOfTheWicked",
  "closure": {
    "site_function": "openPortalSealed",
    "site_call": ".call",
    "functions": ["openPortalSealed"],
    "justification": "openPortalSealed is the only function that writes to the exposed storage and makes an external call."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": ["openPortalSealed"],
    "nesting_bound": {
      "openPortalSealed": 1
    }
  },
  "phases": {
    "function": "openPortalSealed",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The number of demons in transit during the callback window.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "demons == demons + inFlight",
    "stable_formula": "demons == demons",
    "kind": "additive"
  },
  "composition": {
    "target_property": "demons == demons",
    "rule": "The exposure invariant ensures that the number of demons remains consistent during the callback window, accounting for in-flight changes."
  }
}
